Object.assign(window.STUDY_EXAMS,{"mln131_extra":{"subject":"mln131","legacyExamId":"extra","title":"Đề ôn tập 02 · 60 câu đã đối chiếu","short":"MLN131 · Đề 02","storageKey":"mln131_unified_extra_v1","legacyKey":"mln131_unified_extra_v0","mockEnabled":true,"notice":"Đề tổng hợp tiếp theo gồm 60 câu đã xác minh, không lặp câu của Đề 01. Giữ nguyên tiến độ các câu từng nằm ở phần bổ sung; mỗi câu có số gốc, giải thích, gợi ý từ khóa và trang giáo trình.","questions":[{"id":4,"stem":"Cơ cấu kinh tế trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam tuy vận động theo cơ chế thị trường, song vẫn có sự quản lý của chủ thể nào?","options":["Giai cấp công nhân","Đảng Cộng sản Việt Nam","Nhà nước pháp quyền xã hội chủ nghĩa","Tầng lớp thống trị trong xã hội"],"correct":[2],"multiple":false,"gradable":true,"why":[],"topic":"Liên minh và cơ cấu xã hội","detail":"Sách nêu cơ cấu kinh tế trong thời kỳ quá độ tuy vận động theo cơ chế thị trường nhưng có sự quản lý của Nhà nước pháp quyền xã hội chủ nghĩa nhằm xây dựng thành công chủ nghĩa xã hội.","trick":"Thị trường có quản lý → Nhà nước pháp quyền XHCN.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 169 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 46","image":"assets/mln131/bo03/q46.png","sourceExam":"mln131_03","sourceId":46,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 46","keywords":["cơ chế thị trường","sự quản lý","chủ thể nào"]},{"id":5,"stem":"Vấn đề chiến lược, cơ bản, lâu dài và cấp bách trong việc giải quyết mối quan hệ dân tộc và tôn giáo ở Việt Nam hiện nay là gì?","options":["Đảm bảo sự lãnh đạo của Đảng Cộng sản Việt Nam, tuân thủ nguyên tắc, lập trường chính trị của giai cấp công nhân","Đảm bảo các tôn giáo, dân tộc chuyển biến tích cực","Đảm bảo hài hòa lợi ích, giảm thiểu tới mức tối đa mâu thuẫn lợi ích, nhất là mâu thuẫn lợi ích kinh tế","Củng cố mối quan hệ tốt đẹp giữa dân tộc và tôn giáo, củng cố khối đại đoàn kết toàn dân tộc và đoàn kết tôn giáo"],"correct":[3],"multiple":false,"gradable":true,"why":["Nêu nguyên tắc lãnh đạo, không phải nội dung được giáo trình gắn trực tiếp với cụm từ trong câu hỏi.","Diễn đạt chung, không chỉ ra nội dung đoàn kết được hỏi.","Nêu vấn đề lợi ích, không phải nội dung của luận điểm được hỏi ở trang 233.","Đúng: khớp luận điểm về quan hệ tốt đẹp và khối đại đoàn kết dân tộc, tôn giáo."],"topic":"Dân tộc và tôn giáo","detail":"Trong mục định hướng giải quyết mối quan hệ dân tộc và tôn giáo, sách xác định tăng cường mối quan hệ tốt đẹp giữa dân tộc và tôn giáo, củng cố khối đại đoàn kết toàn dân tộc và đoàn kết tôn giáo là vấn đề chiến lược, cơ bản, lâu dài và cấp bách của cách mạng Việt Nam. D khớp trực tiếp với nội dung này.","trick":"Chiến lược, cơ bản, lâu dài và cấp bách → đoàn kết dân tộc và đoàn kết tôn giáo.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 233 (số in trên sách) · Bản trong Source · Nhóm ảnh 04 · Câu gốc 50","image":"assets/mln131/bo04/q50.png","sourceExam":"mln131_04","sourceId":50,"sourceKey":"mln131_unified_04_bank_v1","sourceLegacyKey":"mln131_unified_04_bank_v0","sourceLabel":"Nhóm ảnh 04 · Câu gốc 50","keywords":["chiến lược, cơ bản, lâu dài và cấp bách","dân tộc và tôn giáo"]},{"id":6,"stem":"Theo quan điểm của chủ nghĩa Mác - Lênin, hôn nhân tiến bộ là hôn nhân xuất phát từ đâu?","options":["Từ tình yêu giữa nam và nữ","Từ quan hệ kinh tế - xã hội","Từ cơ sở pháp lý được xã hội công nhận","Từ các yếu tố đạo đức truyền thống"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: là cơ sở được sách nêu trực tiếp khi giải thích hôn nhân tiến bộ.","Điều kiện kinh tế - xã hội tác động đến gia đình, nhưng không phải đáp án cho cơ sở xuất phát của hôn nhân tiến bộ trong đoạn này.","Cơ sở pháp lý liên quan đến việc công nhận hôn nhân; câu hỏi yêu cầu cơ sở xuất phát là tình yêu.","Không phải cơ sở được định nghĩa trong giáo trình; chuẩn mực truyền thống cũng cần được xem xét theo nội dung tiến bộ."],"topic":"Gia đình","detail":"Phần Chế độ hôn nhân tiến bộ, mục Hôn nhân tự nguyện, xác định hôn nhân tiến bộ xuất phát từ tình yêu giữa nam và nữ. Hôn nhân xuất phát từ tình yêu tất yếu dẫn đến hôn nhân tự nguyện. Đây là cơ sở được câu hỏi yêu cầu.","trick":"Hôn nhân tiến bộ → tình yêu → tự nguyện.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 254 (số in trên sách) · Bản trong Source · Nhóm ảnh 04 · Câu gốc 54","image":"assets/mln131/bo04/q54.png","sourceExam":"mln131_04","sourceId":54,"sourceKey":"mln131_unified_04_bank_v1","sourceLegacyKey":"mln131_unified_04_bank_v0","sourceLabel":"Nhóm ảnh 04 · Câu gốc 54","keywords":["hôn nhân tiến bộ","xuất phát từ đâu"]},{"id":7,"stem":"Cơ cấu xã hội - giai cấp của nước ta trong thời kì quá độ lên chủ nghĩa xã hội hiện nay bao gồm những giai cấp, tầng lớp cơ bản nào?","options":["Giai cấp công nhân","Giai cấp nông dân","Đội ngũ trí thức và đội ngũ doanh nhân","Đội ngũ trí thức và đội ngũ đảng viên"],"correct":[0,1,2],"multiple":true,"gradable":true,"why":["Đúng: giai cấp công nhân được trình bày tại trang 178–179.","Đúng: giai cấp nông dân được trình bày tại trang 179–180.","Đúng: đội ngũ trí thức và đội ngũ doanh nhân được trình bày tại trang 180–181.","Sai: tuy có trí thức, phương án ghép thêm đội ngũ đảng viên, không thuộc danh sách các giai cấp, tầng lớp cơ bản được sách nêu."],"topic":"Liên minh và cơ cấu xã hội","detail":"Sách lần lượt trình bày giai cấp công nhân, giai cấp nông dân, đội ngũ trí thức và đội ngũ doanh nhân trong cơ cấu xã hội - giai cấp ở Việt Nam hiện nay. Vì vậy cần chọn A, B và C để đủ bốn nhóm. D ghép trí thức với đảng viên; đảng viên không được liệt kê như một giai cấp, tầng lớp riêng trong danh sách này.","trick":"Hiện nay: công nhân – nông dân – trí thức – doanh nhân; phân biệt với cơ cấu đơn giản trước đổi mới.","caution":"Có ba phương án đúng theo giáo trình. Bản ôn ghi rõ Chọn nhiều đáp án và chấm theo A, B, C; không ép chọn một phương án.","reference":"Giáo trình CNXH khoa học (2021), trang 178–181 (số in trên sách) · Bản trong Source · Nhóm ảnh 04 · Câu gốc 51","image":"assets/mln131/bo04/q51.png","sourceExam":"mln131_04","sourceId":51,"sourceKey":"mln131_unified_04_bank_v1","sourceLegacyKey":"mln131_unified_04_bank_v0","sourceLabel":"Nhóm ảnh 04 · Câu gốc 51","keywords":["cơ cấu xã hội - giai cấp","hiện nay","cơ bản"]},{"id":8,"stem":"Nội dung cốt lõi của công tác tôn giáo ở nước ta hiện nay là gì?","options":["Công tác giáo dục chủ nghĩa duy vật biện chứng","Công tác cảm hóa giáo dân","Công tác vận động quần chúng","Công tác điều hòa mâu thuẫn giữa các tôn giáo"],"correct":[2],"multiple":false,"gradable":true,"why":["Không phải nội dung cốt lõi được giáo trình xác định cho công tác tôn giáo.","Không phải cách xác định nội dung cốt lõi trong giáo trình.","Đúng: sách xác định trực tiếp công tác vận động quần chúng là nội dung cốt lõi.","Không khớp nội dung cốt lõi được hỏi; công tác tôn giáo có phạm vi rộng hơn điều hòa mâu thuẫn."],"topic":"Tôn giáo","detail":"Trong phần chính sách của Đảng, Nhà nước Việt Nam đối với tín ngưỡng, tôn giáo, giáo trình nêu rõ nội dung cốt lõi của công tác tôn giáo là công tác vận động quần chúng. Công tác này gắn với động viên đồng bào, bảo đảm lợi ích và nâng cao đời sống mọi mặt.","trick":"Cốt lõi của công tác tôn giáo → vận động quần chúng.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 227 (số in trên sách) · Bản trong Source · Nhóm ảnh 04 · Câu gốc 56","image":"assets/mln131/bo04/q56.png","sourceExam":"mln131_04","sourceId":56,"sourceKey":"mln131_unified_04_bank_v1","sourceLegacyKey":"mln131_unified_04_bank_v0","sourceLabel":"Nhóm ảnh 04 · Câu gốc 56","keywords":["Nội dung cốt lõi","công tác tôn giáo"]},{"id":9,"stem":"Đâu không phải là tiền đề khoa học tự nhiên cho sự ra đời của chủ nghĩa xã hội khoa học?","options":["Học thuyết tiến hóa","Học thuyết tế bào","Định luật bảo toàn và chuyển hóa năng lượng","Chủ nghĩa xã hội không tưởng của Pháp"],"correct":[3],"multiple":false,"gradable":true,"why":["Là tiền đề khoa học tự nhiên, không chọn khi câu hỏi có chữ KHÔNG.","Là tiền đề khoa học tự nhiên, không chọn khi câu hỏi có chữ KHÔNG.","Là tiền đề khoa học tự nhiên, không chọn khi câu hỏi có chữ KHÔNG.","Đúng theo yêu cầu phủ định: thuộc tiền đề tư tưởng lý luận."],"topic":"Nhập môn chủ nghĩa xã hội khoa học","detail":"Giáo trình xếp học thuyết tiến hóa, học thuyết tế bào, định luật bảo toàn và chuyển hóa năng lượng vào các tiền đề khoa học tự nhiên. Chủ nghĩa xã hội không tưởng Pháp thuộc tiền đề tư tưởng lý luận, nên D trả lời yêu cầu KHÔNG phải tiền đề khoa học tự nhiên.","trick":"Tự nhiên: tiến hóa – tế bào – năng lượng. Không tưởng Pháp thuộc tư tưởng lý luận.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 14–15 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 3","image":"assets/mln131/bo05/q03.png","sourceExam":"mln131_05","sourceId":3,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 3","keywords":["không phải","tiền đề khoa học tự nhiên"]},{"id":10,"stem":"Dựa trên phương diện chính trị - xã hội, giai cấp công nhân được hiểu như thế nào?","options":["Là những người nông dân nghèo bị bóc lột sức lao động","Là những người trí thức tham gia vào sản xuất","Là sản phẩm xã hội của quá trình phát triển tư bản chủ nghĩa","A và B đều đúng"],"correct":[2],"multiple":false,"gradable":true,"why":["Đồng nhất công nhân với nông dân nghèo nên không đúng định nghĩa.","Không thể đồng nhất toàn bộ giai cấp công nhân với trí thức tham gia sản xuất.","Đúng: là nội dung mở đầu mục chính trị - xã hội ở trang 54.","Sai vì cả A và B đều không phải định nghĩa được hỏi."],"topic":"Giai cấp công nhân","detail":"Ngay phần Về phương diện chính trị - xã hội, sách nêu giai cấp công nhân là sản phẩm xã hội của quá trình phát triển tư bản chủ nghĩa. Đoạn tiếp theo giải thích vị trí của người lao động làm thuê, không sở hữu tư liệu sản xuất chủ yếu, phải bán sức lao động và bị bóc lột giá trị thặng dư. C là phương án phù hợp trong bốn lựa chọn.","trick":"Chính trị - xã hội trong câu này → sản phẩm xã hội của sự phát triển tư bản chủ nghĩa.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 54 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 5","image":"assets/mln131/bo05/q05.png","sourceExam":"mln131_05","sourceId":5,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 5","keywords":["phương diện chính trị - xã hội","giai cấp công nhân"]},{"id":11,"stem":"Học thuyết về hình thái kinh tế - xã hội do ai khởi xướng?","options":["C. Mác và V.I. Lênin","Ph. Ăngghen và V.I. Lênin","C. Mác và Ph. Ăngghen","V.I. Lênin và Chủ tịch Hồ Chí Minh"],"correct":[2],"multiple":false,"gradable":true,"why":["Ghép một người khởi xướng với người bổ sung, phát triển.","Ghép một người khởi xướng với người bổ sung, phát triển.","Đúng: đúng cặp tác giả được giáo trình xác định là người khởi xướng.","Không phải cặp tác giả khởi xướng được sách nêu."],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Giáo trình nêu trực tiếp học thuyết về hình thái kinh tế - xã hội do C. Mác và Ph. Ăngghen khởi xướng, được V.I. Lênin bổ sung, phát triển và vận dụng vào thực tiễn nước Nga. Cần phân biệt người khởi xướng với người tiếp tục phát triển.","trick":"Khởi xướng: Mác – Ăngghen; bổ sung, phát triển: Lênin.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 87 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 6","image":"assets/mln131/bo05/q06.png","sourceExam":"mln131_05","sourceId":6,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 6","keywords":["hình thái kinh tế - xã hội","khởi xướng"]},{"id":12,"stem":"Hình thức dân chủ ở Việt Nam mà người dân bầu ra cơ quan quyền lực nhà nước cao nhất, ủy quyền cho họ thực hiện quyền lực của nhân dân được gọi là hình thức dân chủ gì?","options":["Hình thức dân chủ trực tiếp","Hình thức dân chủ gián tiếp","Hình thức dân chủ đại nghị","Hình thức dân chủ công khai"],"correct":[1],"multiple":false,"gradable":true,"why":["Trực tiếp là nhân dân tự thực hiện quyền làm chủ, không qua chủ thể đại diện trung gian.","Đúng: khớp định nghĩa và ví dụ bầu Quốc hội ở trang 153.","Dễ gây nhầm với dân chủ đại diện; trong cặp hình thức được giáo trình phân loại ở đoạn này, tên gọi đúng là gián tiếp, không dùng đại nghị làm đáp án thay thế.","Không phải hình thức được định nghĩa trong đoạn giáo trình này."],"topic":"Dân chủ và nhà nước","detail":"Trong cách phân loại dân chủ trực tiếp và gián tiếp của giáo trình, hình thức nhân dân ủy quyền cho tổ chức do mình bầu ra được gọi là dân chủ gián tiếp, hay dân chủ đại diện. Sách dùng chính ví dụ nhân dân bầu ra Quốc hội để giải thích hình thức này. Vì vậy chọn B theo thuật ngữ của nguồn.","trick":"Bầu đại diện + ủy quyền → dân chủ gián tiếp (đại diện).","caution":"Chốt B theo cách gọi trực tiếp của giáo trình: dân chủ gián tiếp (dân chủ đại diện). Không đồng nhất mọi thuật ngữ liên quan đến nghị viện trong các hệ phân loại khác.","reference":"Giáo trình CNXH khoa học (2021), trang 153 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 20","image":"assets/mln131/bo05/q20.png","sourceExam":"mln131_05","sourceId":20,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 20","keywords":["bầu ra","ủy quyền","hình thức dân chủ"]},{"id":13,"stem":"Nhà nước xã hội chủ nghĩa có vai trò như thế nào đối với dân chủ xã hội chủ nghĩa?","options":["Nhà nước xã hội chủ nghĩa là công cụ trấn áp dân chủ xã hội chủ nghĩa","Nhà nước xã hội chủ nghĩa trở thành công cụ quan trọng cho việc thực thi quyền làm chủ của người dân","Nhà nước xã hội chủ nghĩa là động lực, nền tảng thực hiện dân chủ xã hội chủ nghĩa","Nhà nước xã hội chủ nghĩa là cơ sở, điều kiện tiên quyết cho việc tổ chức dân chủ triệt để đối với mọi giai cấp"],"correct":[1],"multiple":false,"gradable":true,"why":["Trái với vai trò bảo vệ và thực hiện dân chủ được sách nêu.","Đúng: khớp tiêu đề và nội dung mục b ở trang 148.","Không phải cách diễn đạt vai trò của nhà nước trong đoạn này; cần phân biệt chiều dân chủ là cơ sở, nền tảng của nhà nước.","Không đúng: giáo trình không xác định dân chủ triệt để đối với mọi giai cấp."],"topic":"Dân chủ và nhà nước","detail":"Sách phân biệt hai chiều quan hệ: dân chủ xã hội chủ nghĩa là cơ sở, nền tảng cho việc xây dựng và hoạt động của nhà nước; nhà nước xã hội chủ nghĩa trở thành công cụ quan trọng để thực thi quyền làm chủ của người dân. B đúng với chiều quan hệ câu hỏi đang yêu cầu.","trick":"Dân chủ → cơ sở, nền tảng của nhà nước; nhà nước → công cụ thực thi quyền làm chủ.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 147–148 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 24","image":"assets/mln131/bo05/q24.png","sourceExam":"mln131_05","sourceId":24,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 24","keywords":["Nhà nước xã hội chủ nghĩa","vai trò","dân chủ xã hội chủ nghĩa"]},{"id":14,"stem":"Cơ cấu xã hội - giai cấp trong thời kì quá độ lên chủ nghĩa xã hội có sự đan xen giữa cái cũ và cái mới, biểu hiện về mặt kinh tế của nó là gì?","options":["Tồn tại kết cấu kinh tế nhiều thành phần","Tồn tại nhiều giai cấp, tầng lớp đối lập với nhau","Tồn tại nhiều chủ sở hữu trong cùng một doanh nghiệp","Tồn tại nhiều hình thức liên doanh, liên kết tư bản nước ngoài"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: là biểu hiện kinh tế được sách nêu trực tiếp.","Đề cập giai cấp, tầng lớp thay vì biểu hiện về mặt kinh tế được hỏi.","Chỉ là một khả năng trong tổ chức sở hữu, không phải nội dung khái quát mà sách xác định.","Chỉ là một số hình thức kinh tế cụ thể, không khái quát đầy đủ nội dung của nguồn."],"topic":"Liên minh và cơ cấu xã hội","detail":"Sách xác định sự đan xen giữa các yếu tố cũ và mới trong thời kỳ quá độ biểu hiện về mặt kinh tế ở chỗ còn tồn tại kết cấu kinh tế nhiều thành phần. Kết cấu ấy dẫn đến sự đa dạng của cơ cấu xã hội - giai cấp.","trick":"Đan xen cũ – mới, hỏi về kinh tế → nhiều thành phần kinh tế.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 171 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 26","image":"assets/mln131/bo05/q26.png","sourceExam":"mln131_05","sourceId":26,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 26","keywords":["đan xen giữa cái cũ và cái mới","mặt kinh tế"]},{"id":15,"stem":"Quan hệ dân tộc và tôn giáo ở Việt Nam chịu sự chi phối mạnh mẽ bởi yếu tố nào?","options":["Yếu tố giai cấp","Yếu tố quản lý của Nhà nước","Yếu tố tín ngưỡng truyền thống","Yếu tố đại đoàn kết dân tộc"],"correct":[2],"multiple":false,"gradable":true,"why":["Không phải yếu tố được xác định trong luận điểm này.","Có liên quan đến thực tiễn quản lý, nhưng không phải đáp án của đặc điểm được hỏi.","Đúng: đúng tiêu đề và nội dung mục b ở trang 230.","Là mục tiêu, định hướng cần củng cố, không phải yếu tố được gọi là chi phối mạnh trong đoạn này."],"topic":"Dân tộc và tôn giáo","detail":"Trong mục đặc điểm quan hệ dân tộc và tôn giáo ở Việt Nam, sách nêu quan hệ này chịu sự chi phối mạnh mẽ bởi tín ngưỡng truyền thống, đặc biệt các thực hành như thờ cúng tổ tiên và những người có công với dân, với nước.","trick":"Chi phối mạnh quan hệ dân tộc – tôn giáo ở Việt Nam → tín ngưỡng truyền thống.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 230 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 35","image":"assets/mln131/bo05/q35.png","sourceExam":"mln131_05","sourceId":35,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 35","keywords":["dân tộc và tôn giáo","chi phối mạnh mẽ"]},{"id":16,"stem":"Đặc trưng nào dưới đây là quan trọng nhất, là cơ sở gắn kết các bộ phận, các thành viên trong dân tộc, tạo nên tính thống nhất, ổn định, bền vững của dân tộc?","options":["Chung một vùng lãnh thổ","Chung một phương thức sinh hoạt kinh tế","Chung một ngôn ngữ làm công cụ giao tiếp","Chung một nền văn hóa và tâm lý"],"correct":[1],"multiple":false,"gradable":true,"why":["Lãnh thổ là yếu tố thiêng liêng, nhưng không phải đặc trưng được sách gọi quan trọng nhất trong đoạn này.","Đúng: là đặc trưng được sách gắn trực tiếp với cơ sở gắn kết và tính bền vững.","Là đặc trưng chủ yếu của dân tộc, nhưng không khớp cụm quan trọng nhất được hỏi.","Văn hóa, tâm lý tạo bản sắc và liên kết cộng đồng, nhưng không phải đáp án của cụm mô tả này."],"topic":"Dân tộc","detail":"Trong các đặc trưng dân tộc theo nghĩa rộng, sách xác định có chung một phương thức sinh hoạt kinh tế là đặc trưng quan trọng nhất, cơ sở gắn kết các bộ phận và thành viên, tạo tính thống nhất, ổn định, bền vững. Không nhầm với lãnh thổ được sách gọi là yếu tố thiêng liêng.","trick":"Quan trọng nhất, nền tảng gắn kết → sinh hoạt kinh tế chung.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 197–198 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 41","image":"assets/mln131/bo05/q41.png","sourceExam":"mln131_05","sourceId":41,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 41","keywords":["quan trọng nhất","cơ sở gắn kết","ổn định, bền vững"]},{"id":17,"stem":"Nếu thiếu đi cơ sở văn hóa, hoặc cơ sở văn hóa không đi liền với cơ sở kinh tế, chính trị thì việc xây dựng gia đình sẽ bị ảnh hưởng như thế nào?","options":["Việc xây dựng gia đình sẽ lệch lạc, không đạt hiệu quả","Hệ thống chính sách, pháp luật về xây dựng gia đình sẽ không thể hoàn thiện","Việc xây dựng gia đình không còn dựa trên nền tảng hệ tư tưởng chính trị","Việc xây dựng gia đình sẽ không hướng tới đời sống văn hóa, tinh thần"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: khớp kết luận mục Cơ sở văn hóa ở trang 253.","Không phải hệ quả được giáo trình nêu trong câu đang hỏi.","Không phải cách kết luận của nguồn; phương án suy rộng quá nội dung đoạn văn.","Không phải cách kết luận của nguồn."],"topic":"Gia đình","detail":"Kết luận mục Cơ sở văn hóa nêu rõ thiếu cơ sở văn hóa, hoặc cơ sở văn hóa không đi liền với cơ sở kinh tế và chính trị, sẽ làm việc xây dựng gia đình lệch lạc, không đạt hiệu quả cao. A khớp nội dung này.","trick":"Thiếu cơ sở văn hóa hoặc không đồng bộ → lệch lạc, kém hiệu quả.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 253 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 42","image":"assets/mln131/bo05/q42.png","sourceExam":"mln131_05","sourceId":42,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 42","keywords":["thiếu đi cơ sở văn hóa","không đi liền"]},{"id":18,"stem":"Hôn nhân một vợ một chồng xuất hiện lần đầu tiên khi nào?","options":["Khi có sự thắng lợi của chế độ tư hữu đối với chế độ công hữu nguyên thủy","Khi có sự thắng thế của chế độ tư bản đối với chế độ phong kiến","Khi các quốc gia bước vào thời kỳ quá độ lên chủ nghĩa xã hội","Khi con người xuất hiện"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: đúng mốc lịch sử được giáo trình nêu.","Muộn hơn thời điểm xuất hiện được sách xác định.","Thời kỳ quá độ liên quan đến xây dựng hôn nhân tiến bộ, bình đẳng, không phải lần đầu có một vợ một chồng.","Không phải mốc được giáo trình nêu."],"topic":"Gia đình","detail":"Sách nêu hôn nhân một vợ một chồng xuất hiện từ sớm khi chế độ tư hữu thắng thế chế độ công hữu nguyên thủy. Đồng thời sách lưu ý trong các xã hội trước, chế độ ấy thực chất chỉ ràng buộc người phụ nữ; không đồng nhất sự xuất hiện sớm với mô hình vợ chồng bình đẳng trong chủ nghĩa xã hội.","trick":"Lần đầu xuất hiện → tư hữu thắng công hữu nguyên thủy; chưa có nghĩa vợ chồng đã bình đẳng.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 255 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 45","image":"assets/mln131/bo05/q45.png","sourceExam":"mln131_05","sourceId":45,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 45","keywords":["Hôn nhân một vợ một chồng","lần đầu tiên"]},{"id":19,"stem":"Câu khẳng định: “Nếu không giải phóng phụ nữ là xây dựng chủ nghĩa xã hội chỉ một nửa” là của ai?","options":["Các Mác","Ph. Ăngghen","V.I. Lênin","Hồ Chí Minh"],"correct":[3],"multiple":false,"gradable":true,"why":["C. Mác gắn với lý luận giải phóng giai cấp, giải phóng con người, nhưng không phải tác giả câu được hỏi theo giáo trình.","Ph. Ăngghen có những phân tích về gia đình, tư hữu và địa vị phụ nữ, nhưng không phải tác giả câu này.","V.I. Lênin có các luận điểm về giải phóng phụ nữ và nhà nước Xôviết, nhưng không phải tác giả câu này.","Đúng: giáo trình trang 245 ghi rõ tác giả và chú thích nguồn Hồ Chí Minh: Toàn tập."],"topic":"Gia đình và giải phóng phụ nữ","detail":"Trong phần vị trí của gia đình và mối quan hệ gia đình với xã hội, giáo trình dẫn chính câu nói này và xác định tác giả là Chủ tịch Hồ Chí Minh. Chú thích ở cuối trang dẫn Hồ Chí Minh: Toàn tập, tập 13, trang 300. Vì vậy đáp án là D.","trick":"Không giải phóng phụ nữ → xây dựng CNXH chỉ một nửa → Hồ Chí Minh.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 245 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 49","image":"assets/mln131/bo05/q49.png","studyNote":{"title":"Ghi nhớ 4 nhà tư tưởng — theo note bên phải ảnh câu 49","columns":["Nhà tư tưởng","Nội dung ghi nhớ"],"rows":[["C. Mác","Giải phóng giai cấp, giải phóng con người"],["Ph. Ăngghen","Nguồn gốc gia đình, chế độ tư hữu và địa vị phụ nữ"],["V.I. Lênin","Vai trò của phụ nữ trong cách mạng xã hội chủ nghĩa"],["Hồ Chí Minh","Không giải phóng phụ nữ thì xây dựng CNXH chỉ một nửa"]],"caption":"Bảng chép theo ghi chú ở cột bình luận bên phải ảnh. Các dòng khái quát là từ khóa gợi nhớ, không phải bốn trích dẫn nguyên văn hoặc khẳng định mỗi chủ đề chỉ thuộc một tác giả. Câu nói được hỏi đã được kiểm chứng ở giáo trình trang 245; các nội dung về giải phóng phụ nữ cũng được bàn tại trang 250–252."},"sourceExam":"mln131_05","sourceId":49,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 49","keywords":["không giải phóng phụ nữ","chỉ một nửa","của ai"]},{"id":20,"stem":"Những biến đổi và khác biệt của giai cấp công nhân hiện đại so với giai cấp công nhân thế kỉ XIX là gì?","options":["Xu hướng trí tuệ hóa tăng nhanh","Xu hướng trung lưu hóa gia tăng","Là giai cấp giữ vai trò lãnh đạo, cầm quyền trong quá trình xây dựng chủ nghĩa xã hội ở một số quốc gia","Xu hướng bần cùng hóa gia tăng nhanh chóng"],"correct":[0,1,2],"multiple":true,"gradable":true,"why":["Đúng: là xu hướng thứ nhất được sách trình bày tại trang 67.","Đúng: là xu hướng thứ hai được trình bày tại trang 67–68.","Đúng theo ý của mục này; nói chính xác, giai cấp công nhân lãnh đạo, Đảng Cộng sản là đội tiên phong giữ vai trò cầm quyền.","Không thuộc danh sách biến đổi được nêu; sách không từ xu hướng trung lưu hóa mà phủ nhận việc công nhân còn bị bóc lột."],"topic":"Giai cấp công nhân","detail":"Mục Những biến đổi và khác biệt của giai cấp công nhân hiện đại lần lượt trình bày xu hướng trí tuệ hóa, xu hướng trung lưu hóa và vai trò lãnh đạo của giai cấp công nhân cùng vai trò cầm quyền của đội tiên phong ở một số quốc gia xã hội chủ nghĩa. Do đó A, B, C được nguồn xác nhận. D không phải xu hướng được liệt kê trong mục này.","trick":"Biến đổi hiện đại: trí tuệ hóa – trung lưu hóa – vai trò lãnh đạo ở một số nước XHCN.","caution":"Có nhiều đáp án đúng; bản ôn ghi rõ chọn A, B, C. Trung lưu hóa về mức sống không đồng nghĩa hết bị bóc lột hay nắm quyền quyết định sản xuất.","reference":"Giáo trình CNXH khoa học (2021), trang 67–68 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 50","image":"assets/mln131/bo05/q50.png","sourceExam":"mln131_05","sourceId":50,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 50","keywords":["biến đổi và khác biệt","công nhân hiện đại","thế kỉ XIX"]},{"id":21,"stem":"Cho đến nay, kinh tế gia đình Việt Nam đã có bước chuyển biến mang tính bước ngoặt nào? Chọn các đáp án đúng.","options":["Từ kinh tế tự cấp, tự túc thành kinh tế hàng hóa","Từ kinh tế hàng hóa thành kinh tế tự cấp, tự túc","Từ đơn vị kinh tế đáp ứng nhu cầu của thị trường quốc gia thành đơn vị kinh tế đáp ứng nhu cầu của thị trường toàn cầu","Từ kinh tế kế hoạch hóa tập trung sang kinh tế thị trường tự do"],"correct":[0,2],"multiple":true,"gradable":true,"why":["Đúng: bước chuyển thứ nhất ở trang 260.","Sai: đảo ngược chiều bước chuyển mà sách nêu.","Đúng: bước chuyển thứ hai được trình bày tiếp ở trang 260–261.","Không phải nội dung hai bước chuyển về kinh tế gia đình trong đoạn này."],"topic":"Gia đình","detail":"Sách nêu hai bước chuyển: từ kinh tế tự cấp tự túc sang kinh tế hàng hóa; từ đơn vị sản xuất hàng hóa đáp ứng thị trường quốc gia thành tổ chức kinh tế đáp ứng thị trường toàn cầu. A và C đúng, B đảo chiều bước chuyển thứ nhất, D không phải hai bước chuyển của kinh tế gia đình được hỏi.","trick":"Hai bước: tự cấp → hàng hóa; thị trường quốc gia → toàn cầu.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 260–261 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 53","image":"assets/mln131/bo05/q53.png","sourceExam":"mln131_05","sourceId":53,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 53","keywords":["kinh tế gia đình","bước ngoặt"]},{"id":22,"stem":"Đâu là một trong những điều kiện ra đời chủ nghĩa xã hội khoa học?","options":["Điều kiện kinh tế - xã hội","Điều kiện văn hóa - xã hội","Điều kiện chính trị - xã hội","Điều kiện khoa học"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: là mục Điều kiện kinh tế - xã hội tại trang 12–14.","Không phải tên điều kiện được giáo trình liệt kê trong phần này.","Không phải tên điều kiện được tách thành mục ở phần này; phong trào công nhân có tính chính trị được trình bày trong điều kiện kinh tế - xã hội.","Khoa học tự nhiên có vai trò tiền đề; giáo trình gọi đó là tiền đề, không dùng tên mục Điều kiện khoa học như lựa chọn này."],"topic":"Nhập môn chủ nghĩa xã hội khoa học","detail":"Trong phần Hoàn cảnh lịch sử ra đời chủ nghĩa xã hội khoa học, giáo trình chia thành Điều kiện kinh tế - xã hội và Tiền đề khoa học tự nhiên và tư tưởng lý luận. A là tên mục điều kiện được nêu trực tiếp; các phương án còn lại không khớp cách phân mục này.","trick":"Phân mục trong sách: điều kiện kinh tế - xã hội; tiền đề khoa học tự nhiên và tư tưởng lý luận.","caution":"Chọn A theo cách phân mục của giáo trình; không hiểu việc loại D là phủ nhận vai trò của các tiền đề khoa học tự nhiên.","reference":"Giáo trình CNXH khoa học (2021), trang 12–17 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 55","image":"assets/mln131/bo05/q55.png","sourceExam":"mln131_05","sourceId":55,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 55","keywords":["điều kiện ra đời","chủ nghĩa xã hội khoa học"]},{"id":23,"stem":"Những yếu tố nào dưới đây khẳng định dân chủ xã hội chủ nghĩa là nền dân chủ cao hơn về chất so với các nền dân chủ trước đó? (Câu hỏi lựa chọn nhiều đáp án)","options":["Mọi quyền lực thuộc về nhân dân","Quyền lực thuộc về giai cấp công nhân","Được thực hiện bằng Nhà nước pháp quyền xã hội chủ nghĩa","Do Đảng Cộng sản lãnh đạo"],"correct":[0,2,3],"multiple":true,"gradable":true,"why":["Đúng: đúng chủ thể của mọi quyền lực trong định nghĩa ở trang 134.","Không chọn: cần phân biệt giai cấp công nhân lãnh đạo với mọi quyền lực thuộc về nhân dân; không giới hạn quyền lực chỉ ở công nhân.","Đúng: đúng hình thức thực hiện dân chủ trong định nghĩa ở trang 134.","Đúng: đúng yếu tố lãnh đạo được định nghĩa ở trang 134."],"topic":"Dân chủ và nhà nước","detail":"Đoạn khái quát tại trang 134 nêu dân chủ xã hội chủ nghĩa là nền dân chủ mà mọi quyền lực thuộc về nhân dân, được thực hiện bằng Nhà nước pháp quyền xã hội chủ nghĩa, đặt dưới sự lãnh đạo của Đảng Cộng sản. Do đó A, C, D khớp trực tiếp. Trang 136 phân biệt sự lãnh đạo của giai cấp công nhân thông qua Đảng với việc thực hiện quyền lực, lợi ích của toàn thể nhân dân, không chỉ riêng công nhân; B thu hẹp chủ thể quyền lực so với định nghĩa được hỏi.","trick":"Quyền lực của nhân dân – Nhà nước pháp quyền XHCN – Đảng Cộng sản lãnh đạo.","caution":"Chọn nhiều đáp án A, C, D; phân biệt chủ thể của quyền lực với giai cấp lãnh đạo thông qua Đảng.","reference":"Giáo trình CNXH khoa học (2021), trang 134, 136 (số in trên sách) · Bản trong Source · Nhóm ảnh 05 · Câu gốc 58","image":"assets/mln131/bo05/q58.png","sourceExam":"mln131_05","sourceId":58,"sourceKey":"mln131_unified_05_bank_v1","sourceLegacyKey":"mln131_unified_05_bank_v0","sourceLabel":"Nhóm ảnh 05 · Câu gốc 58","keywords":["dân chủ cao hơn về chất","lựa chọn nhiều đáp án"]},{"id":24,"stem":"Căn cứ vào phạm vi tác động của quyền lực nhà nước, chức năng của nhà nước xã hội chủ nghĩa được chia thành những chức năng nào?","options":["Chức năng kinh tế và chức năng chính trị","Chức năng văn hóa và chức năng xã hội","Chức năng trấn áp và chức năng tổ chức","Chức năng đối nội và chức năng đối ngoại"],"correct":[3],"multiple":false,"gradable":true,"why":["Thuộc cách phân loại theo lĩnh vực tác động, không phải phạm vi.","Thuộc cách phân loại theo lĩnh vực tác động, không phải phạm vi.","Thuộc cách phân loại theo tính chất quyền lực.","Đúng: đối nội và đối ngoại là hai chức năng theo phạm vi tác động."],"topic":"Dân chủ và nhà nước","detail":"Sách chia chức năng nhà nước theo ba căn cứ khác nhau: phạm vi tác động → đối nội và đối ngoại; lĩnh vực tác động → chính trị, kinh tế, văn hóa, xã hội; tính chất của quyền lực → giai cấp (trấn áp) và xã hội (tổ chức, xây dựng). Đề hỏi phạm vi nên chọn D.","trick":"Phạm vi → trong/ngoài; lĩnh vực → chính trị, kinh tế, văn hóa, xã hội; tính chất → trấn áp/tổ chức.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 144–145 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 3","image":"assets/mln131/bo06/q03.png","sourceExam":"mln131_06","sourceId":3,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 3","keywords":["phạm vi tác động","chức năng"]},{"id":25,"stem":"Đánh giá sau được trích trong tác phẩm nào: “tác phẩm chủ yếu và cơ bản ấy trình bày chủ nghĩa xã hội khoa học... những yếu tố từ đó nảy sinh ra chế độ tương lai”?","options":["Chống Đuyring","Đường Kách mệnh","Tuyên ngôn của Đảng Cộng sản","Tư bản"],"correct":[3],"multiple":false,"gradable":true,"why":["Sách giới thiệu ba phần của Chống Đuyrinh ngay sau đó; đây không phải tác phẩm được câu đánh giá nhắc tới.","Không phải tác phẩm được sách gắn với đánh giá này.","Không phải tác phẩm được sách gắn với đánh giá này.","Đúng với ý hỏi về tác phẩm được Lênin đánh giá: bộ Tư bản."],"topic":"Nhập môn chủ nghĩa xã hội khoa học","detail":"Trang 12 giới thiệu đây là đánh giá của V.I. Lênin về bộ Tư bản; trang 23 nhắc lại đánh giá ấy. Trong bốn lựa chọn, D là tác phẩm được đánh giá. Tuy nhiên, cách hỏi “được trích trong tác phẩm nào” chưa chính xác: câu nhận xét là của Lênin về Tư bản, không có nghĩa Mác viết câu tự nhận xét ấy trong Tư bản. Chú thích trang 12 dẫn V.I. Lênin: Toàn tập, tập 1, trang 226.","trick":"“Tác phẩm chủ yếu và cơ bản… trình bày CNXH khoa học” → Lênin đánh giá bộ Tư bản.","caution":"Đáp án D chỉ tác phẩm được nhận xét. Câu chữ “trích trong” trên ảnh dễ làm nhầm tác phẩm được nhận xét với nguồn của lời nhận xét.","reference":"Giáo trình CNXH khoa học (2021), trang 12, 23 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 7","image":"assets/mln131/bo06/q07.png","sourceExam":"mln131_06","sourceId":7,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 7","keywords":["tác phẩm chủ yếu và cơ bản","trình bày chủ nghĩa xã hội khoa học"]},{"id":26,"stem":"Theo quan điểm của chủ nghĩa Mác - Lênin, từ chủ nghĩa tư bản lên chủ nghĩa xã hội tất yếu phải trải qua thời kỳ gì?","options":["Phát triển của loài người","Phát triển lực lượng sản xuất và quan hệ sản xuất","Quá độ chính trị","Thay đổi phương thức sản xuất"],"correct":[2],"multiple":false,"gradable":true,"why":["Diễn đạt quá rộng, không phải tên thời kỳ được nêu.","Nêu các nội dung biến đổi, không phải tên thời kỳ được hỏi.","Đúng: khớp luận điểm trực tiếp ở trang 104.","Nêu sự thay đổi chung, không phải tên thời kỳ trong đoạn sách."],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Mục Tính tất yếu khách quan của thời kỳ quá độ lên chủ nghĩa xã hội nêu trực tiếp: từ chủ nghĩa tư bản lên chủ nghĩa xã hội tất yếu phải trải qua thời kỳ quá độ chính trị. C khớp thuật ngữ được sách sử dụng.","trick":"Hỏi tên thời kỳ giữa hai chế độ → quá độ chính trị.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 104 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 17","image":"assets/mln131/bo06/q17.png","sourceExam":"mln131_06","sourceId":17,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 17","keywords":["từ chủ nghĩa tư bản lên chủ nghĩa xã hội","thời kỳ"]},{"id":27,"stem":"“Kiện toàn tổ chức, đổi mới phương thức và nâng cao hiệu quả hoạt động của Quốc hội để đảm bảo đây là cơ quan...” Từ nào còn thiếu trong câu trên?","options":["Quyền lực của nhân dân","Quyền lực cao nhất của nhà nước","Quyền lực cao nhất của nhân dân","Quyền lực cao nhất của giai cấp"],"correct":[2],"multiple":false,"gradable":true,"why":["Thiếu cụm cao nhất so với nguyên văn cần điền.","Dễ nhầm với câu tiếp theo về cơ quan quyền lực nhà nước cao nhất; không phải phần còn thiếu của câu trích này.","Đúng: đúng nguyên văn phần còn thiếu ở trang 162.","Không phải phần còn thiếu trong nguồn."],"topic":"Dân chủ và nhà nước","detail":"Đây là bài điền đúng câu trích. Ở trang 162, sau cụm “để đảm bảo đây là cơ quan”, sách viết “quyền lực cao nhất của nhân dân”, nên chọn C. Ngay câu tiếp theo, sách mới viết “Quốc hội là cơ quan quyền lực nhà nước cao nhất ở nước ta”. Hai cách diễn đạt xuất hiện cạnh nhau; B phù hợp với ý của câu tiếp theo nhưng không điền đúng câu đang trích.","trick":"Điền đúng câu “Kiện toàn tổ chức…” → cao nhất của nhân dân (C). Đọc nguyên câu, đừng chọn theo câu kế tiếp.","caution":"Chọn C theo câu trích cụ thể của giáo trình. Không suy ra từ đây rằng cách mô tả Quốc hội là cơ quan quyền lực nhà nước cao nhất là sai.","reference":"Giáo trình CNXH khoa học (2021), trang 162 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 22","image":"assets/mln131/bo06/q22.png","sourceExam":"mln131_06","sourceId":22,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 22","keywords":["Kiện toàn tổ chức","Quốc hội","còn thiếu"]},{"id":28,"stem":"Với tư cách là một hình thái nhà nước, nền dân chủ nào là nền dân chủ của tất cả mọi người?","options":["Dân chủ chủ nô","Dân chủ tư sản","Dân chủ xã hội chủ nghĩa","Không có bất cứ nền dân chủ nào là của tất cả mọi người"],"correct":[3],"multiple":false,"gradable":true,"why":["Theo sách, dân chủ chủ nô phục vụ giai cấp chủ nô.","Theo sách, dân chủ tư sản mang bản chất giai cấp tư sản.","Theo sách, dân chủ XHCN vì lợi ích đa số nhân dân lao động, không đồng nghĩa cho tất cả mọi người.","Đúng trong hệ khái niệm và điều kiện phân loại mà câu hỏi sử dụng."],"topic":"Dân chủ và nhà nước","detail":"Theo cách tiếp cận của giáo trình, dân chủ với tư cách hình thức tổ chức nhà nước có tính giai cấp. Trang 135 còn nhấn mạnh dân chủ vô sản cũng không phải dân chủ cho tất cả mọi người, mà vì lợi ích của đa số quần chúng lao động và bị bóc lột. Vì vậy đáp án D phù hợp với điều kiện “với tư cách là một hình thái nhà nước”.","trick":"Có điều kiện “hình thái nhà nước” → tính giai cấp → không có dân chủ cho tất cả mọi người.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 131–132, 135 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 27","image":"assets/mln131/bo06/q27.png","sourceExam":"mln131_06","sourceId":27,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 27","keywords":["hình thái nhà nước","tất cả mọi người"]},{"id":29,"stem":"Đâu không phải là một trong những loại của cơ cấu xã hội?","options":["Cơ cấu xã hội - giai cấp","Cơ cấu xã hội - nghề nghiệp","Cơ cấu xã hội - hạ tầng","Cơ cấu xã hội - tôn giáo"],"correct":[2],"multiple":false,"gradable":true,"why":["Là một loại cơ cấu xã hội được sách nêu.","Là một loại cơ cấu xã hội được sách nêu.","Đúng theo yêu cầu phủ định: không phải loại trong cách phân loại này.","Là một loại cơ cấu xã hội được sách nêu."],"topic":"Liên minh và cơ cấu xã hội","detail":"Trang 166 liệt kê các loại cơ cấu xã hội như dân cư, nghề nghiệp, giai cấp, dân tộc, tôn giáo. A, B, D là các loại được nêu. C không thuộc cách phân loại này; không nhầm cơ cấu xã hội với khái niệm cơ sở hạ tầng.","trick":"Cơ cấu xã hội phân theo cộng đồng, nhóm người; “hạ tầng” là phương án lạc nhóm.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 166 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 33","image":"assets/mln131/bo06/q33.png","sourceExam":"mln131_06","sourceId":33,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 33","keywords":["không phải","loại","cơ cấu xã hội"]},{"id":30,"stem":"Trong cơ cấu xã hội - giai cấp ở Việt Nam hiện nay, giai cấp, tầng lớp nào đang đóng góp tích cực vào việc thực hiện chiến lược phát triển kinh tế - xã hội, tạo việc làm cho người lao động?","options":["Giai cấp công nhân","Giai cấp nông dân","Tầng lớp trí thức","Tầng lớp doanh nhân"],"correct":[3],"multiple":false,"gradable":true,"why":["Có vai trò lớn trong sản xuất, nhưng không phải chủ thể của đoạn mô tả đang được trích.","Không phải chủ thể được đoạn sách này nhắc trực tiếp.","Sách nhấn mạnh vai trò tri thức và khoa học - công nghệ ở phần khác; không phải đoạn mô tả này.","Đúng: các đóng góp nêu trong câu được trình bày tại mục đội ngũ doanh nhân."],"topic":"Liên minh và cơ cấu xã hội","detail":"Đoạn về đội ngũ doanh nhân ở trang 181 nêu đóng góp vào chiến lược phát triển kinh tế - xã hội, giải quyết việc làm và các vấn đề an sinh xã hội. D là nhóm được đoạn mô tả nhắc trực tiếp. Không suy ra rằng các nhóm khác không góp phần tạo việc làm.","trick":"Mô tả đội ngũ gắn với phát triển kinh tế, giải quyết việc làm, an sinh → doanh nhân.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 181 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 35","image":"assets/mln131/bo06/q35.png","sourceExam":"mln131_06","sourceId":35,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 35","keywords":["chiến lược phát triển kinh tế - xã hội","tạo việc làm"]},{"id":31,"stem":"Làm sao để xóa bỏ triệt để, ngay lập tức các giai cấp, tầng lớp của cơ cấu xã hội - giai cấp trong thời kỳ quá độ lên chủ nghĩa xã hội?","options":["Giai cấp công nhân, liên minh cùng với các giai cấp, tầng lớp khác tổ chức nhà nước và thực hiện công cụ chuyên chính vô sản thực thi xóa bỏ ngay lập tức giai cấp tư sản, và sau đó xóa bỏ luôn giai cấp mình","Các giai cấp, tầng lớp chủ động đứng vào hàng ngũ của Đảng Cộng sản để thống nhất xóa bỏ sự tồn tại của giai cấp","Sự tồn tại các giai cấp, tầng lớp trong thời kỳ quá độ lên chủ nghĩa xã hội là vấn đề mang tính quy luật, chỉ có thể cải tạo dần chứ chưa thể xóa bỏ triệt để, ngay lập tức được","Quốc hữu hóa tất cả tài sản, tịch thu ruộng đất, gia sản của giai cấp tư sản, đồng thời biến họ trở thành nhân dân lao động"],"correct":[2],"multiple":false,"gradable":true,"why":["Trái với sự tồn tại có tính quy luật và quá trình biến đổi lâu dài được sách mô tả.","Tư cách đảng viên không tự xóa bỏ các quan hệ kinh tế - xã hội cấu thành giai cấp.","Đúng: phản bác yêu cầu xóa bỏ ngay lập tức, phù hợp với quy luật và quá trình cải biến lâu dài.","Không thể suy ra từ các biện pháp sở hữu rằng cơ cấu giai cấp bị xóa bỏ triệt để ngay lập tức."],"topic":"Liên minh và cơ cấu xã hội","detail":"Câu hỏi đặt một tiền đề không đúng: có thể xóa bỏ toàn bộ giai cấp, tầng lớp ngay lập tức. Sách xác định sự đan xen cũ - mới, kinh tế nhiều thành phần và sự tồn tại nhiều giai cấp, tầng lớp là có tính quy luật. Sự xích lại gần nhau, từng bước xóa bỏ bóc lột và bất bình đẳng là một quá trình lâu dài qua các cải biến toàn diện. Vì vậy C phù hợp; các biện pháp hành chính tức thời ở A, B, D không thay thế được quá trình này.","trick":"Thấy “triệt để, ngay lập tức” → kiểm tra tiền đề; quá độ là quá trình cải biến lâu dài.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 171–172 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 36","image":"assets/mln131/bo06/q36.png","sourceExam":"mln131_06","sourceId":36,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 36","keywords":["triệt để, ngay lập tức","giai cấp, tầng lớp"]},{"id":32,"stem":"Đâu là truyền thống quý báu của các dân tộc ở Việt Nam góp phần quyết định mọi thắng lợi của dân tộc trong các giai đoạn lịch sử?","options":["Chống giặc ngoại xâm","Đoàn kết dân tộc","Tinh thần học tập không ngừng","Hiếu thảo với ông bà cha mẹ"],"correct":[1],"multiple":false,"gradable":true,"why":["Là một truyền thống quan trọng, nhưng không phải tên truyền thống được đoạn sách gắn với cụm mô tả này.","Đúng: khớp đặc điểm thứ năm ở trang 208.","Không phải nội dung của đoạn sách đang hỏi.","Không phải nội dung của đoạn sách đang hỏi."],"topic":"Dân tộc","detail":"Trong đặc điểm thứ năm của các dân tộc Việt Nam, sách xác định đoàn kết dân tộc là truyền thống quý báu, một trong những nguyên nhân và động lực quyết định mọi thắng lợi qua các giai đoạn lịch sử. B khớp nội dung này; sách không xem đây là nguyên nhân duy nhất.","trick":"Truyền thống quý báu, động lực quyết định thắng lợi → đoàn kết dân tộc.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 208 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 37","image":"assets/mln131/bo06/q37.png","sourceExam":"mln131_06","sourceId":37,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 37","keywords":["truyền thống quý báu","quyết định mọi thắng lợi"]},{"id":33,"stem":"Để các nước đang trong thời kỳ quá độ lên chủ nghĩa xã hội xây dựng được cơ sở kinh tế vững mạnh, chế độ chính trị xã hội ngày càng được củng cố vững chắc thì cần phải có sự liên minh của những lực lượng nào?","options":["Giai cấp công nhân, giai cấp nông dân, tầng lớp nhân dân lao động khác","Giai cấp nông nhân, giai cấp tư sản, chính quyền","Giai cấp nông nhân, đội ngũ trí thức, đội ngũ doanh nghiệp","Giai cấp công nhân, đội ngũ trí thức, đội ngũ doanh nghiệp"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: khớp đầy đủ ba nhóm trong luận điểm của sách.","Không khớp lực lượng của liên minh mà sách xác định.","Thiếu công nhân; cũng không khớp cách gọi các nhóm trong nguồn.","Thiếu nông dân nên không đủ các lực lượng của liên minh được hỏi."],"topic":"Liên minh và cơ cấu xã hội","detail":"Trang 175 nêu thực hiện tốt liên minh giữa công nhân với nông dân và các tầng lớp nhân dân lao động khác, trước hết là trí thức, sẽ vừa xây dựng cơ sở kinh tế vững mạnh vừa củng cố chế độ chính trị xã hội chủ nghĩa. A phù hợp; trí thức được bao hàm trong các tầng lớp nhân dân lao động khác ở cách trả lời này.","trick":"Liên minh: công nhân + nông dân + các tầng lớp lao động khác, trước hết là trí thức.","caution":"Các phương án B, C giữ lỗi chữ “nông nhân”, C, D giữ “đội ngũ doanh nghiệp” như ảnh; không dùng các lỗi chữ này làm căn cứ duy nhất để chọn đáp án.","reference":"Giáo trình CNXH khoa học (2021), trang 175 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 53","image":"assets/mln131/bo06/q53.png","sourceExam":"mln131_06","sourceId":53,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 53","keywords":["cơ sở kinh tế vững mạnh","liên minh","lực lượng nào"]},{"id":34,"stem":"Chọn đáp án chính xác nhất điền vào chỗ trống trong câu sau: Chủ nghĩa duy vật lịch sử ra đời dựa trên cơ sở kế thừa “...” của phép biện chứng và phê phán quan điểm duy tâm, thần bí của Hêghen.","options":["Cái tổng thể và khái quát","Cái hạt nhân hợp lý","Thực tiễn khách quan","Chủ nghĩa duy vật biện chứng"],"correct":[1],"multiple":false,"gradable":true,"why":["Không phải cụm từ được sách dùng.","Đúng: điền đúng cụm từ ở trang 19.","Không phải phần còn thiếu trong câu trích.","Là khái niệm liên quan trong tiến trình lý luận, không phải cụm từ cần điền."],"topic":"Nhập môn chủ nghĩa xã hội khoa học","detail":"Phần Ba phát kiến vĩ đại nêu Mác và Ăngghen kế thừa “cái hạt nhân hợp lý” của phép biện chứng Hêghen, phê phán quan điểm duy tâm, thần bí; đồng thời kế thừa các giá trị duy vật của Phoiơbắc, sáng lập duy vật biện chứng rồi nghiên cứu xã hội để phát triển duy vật lịch sử. B điền đúng cụm từ. Không đồng nhất hạt nhân hợp lý với toàn bộ hệ thống triết học Hêghen.","trick":"Kế thừa Hêghen → hạt nhân hợp lý của phép biện chứng; phê phán duy tâm, thần bí.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 19 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 60","image":"assets/mln131/bo06/q60.png","sourceExam":"mln131_06","sourceId":60,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 60","keywords":["kế thừa","phép biện chứng","Hêghen"]},{"id":35,"stem":"Quá độ lên chủ nghĩa xã hội bỏ qua chế độ tư bản chủ nghĩa là tạo ra sự biến đổi như thế nào của xã hội trên tất cả các lĩnh vực?","options":["Biến đổi về lượng","Biến đổi về chất","Khuynh hướng phát triển","Thực hiện bước nhảy"],"correct":[1],"multiple":false,"gradable":true,"why":["Không khớp tính chất biến đổi mà sách nêu.","Đúng: đúng luận điểm thứ tư ở trang 112.","Không trả lời cụ thể tính chất biến đổi được hỏi.","Không phải cách diễn đạt trong đoạn; không suy ra có thể bỏ qua quá trình cải biến lâu dài."],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Luận điểm thứ tư ở trang 112 nêu con đường này tạo ra sự biến đổi về chất trên tất cả các lĩnh vực, là sự nghiệp khó khăn, phức tạp, lâu dài. B khớp trực tiếp. Bỏ qua chế độ tư bản chủ nghĩa không có nghĩa bỏ qua mọi thành tựu của nhân loại dưới chủ nghĩa tư bản hay hoàn thành biến đổi ngay lập tức.","trick":"Hỏi kiểu biến đổi trên tất cả lĩnh vực → về chất; quá trình thực hiện vẫn lâu dài.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 111–112 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 59","image":"assets/mln131/bo06/q59.png","sourceExam":"mln131_06","sourceId":59,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 59","keywords":["bỏ qua chế độ tư bản chủ nghĩa","biến đổi","tất cả các lĩnh vực"]},{"id":36,"stem":"Phần lớn các tín đồ tôn giáo ở nước ta có đặc điểm chung là gì?","options":["Là nhân dân lao động, có lòng yêu nước, tinh thần dân tộc","Là giai cấp yếu thế, có cuộc sống cơ cực, tin vào tôn giáo như một yếu tố giải thoát","Có ý thức chống lại chủ nghĩa duy vật biện chứng","Tham gia vào các phong trào đấu tranh chống chính quyền"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: đúng tiêu đề đặc điểm thứ ba ở trang 224.","Không đúng cách khái quát trong sách; tín đồ đa dạng về thành phần và không phải một giai cấp riêng.","Không thể đồng nhất có niềm tin tôn giáo với ý thức chống lại một học thuyết.","Trái với mô tả chủ đạo về tinh thần yêu nước, gắn bó dân tộc trong đoạn sách."],"topic":"Tôn giáo","detail":"Đặc điểm thứ ba của tôn giáo ở Việt Nam xác định tín đồ phần lớn là nhân dân lao động, có lòng yêu nước, tinh thần dân tộc. A khớp trực tiếp. Đây là nhận xét “phần lớn”, không phải kết luận về mọi tín đồ; không coi tín đồ như một giai cấp riêng hoặc đồng nhất niềm tin tôn giáo với thái độ chính trị chống đối.","trick":"Đặc điểm thứ ba của tín đồ Việt Nam → lao động, yêu nước, tinh thần dân tộc.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 224 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 42","image":"assets/mln131/bo06/q42.png","sourceExam":"mln131_06","sourceId":42,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 42","keywords":["Phần lớn","tín đồ tôn giáo","đặc điểm chung"]},{"id":37,"stem":"“Do lực lượng sản xuất chưa phát triển, con người cảm thấy yếu đuối, bất lực, không giải thích được, nên con người đã gán cho tự nhiên một sức mạnh, quyền lực thần bí”, vấn đề này nói lên nguồn gốc nào của tôn giáo?","options":["Nguồn gốc tâm lý","Nguồn gốc nhận thức","Nguồn gốc tự nhiên, kinh tế - xã hội","Nguồn gốc ý chí"],"correct":[2],"multiple":false,"gradable":true,"why":["Dễ nhầm vì có cảm giác bất lực; tuy nhiên đoạn được trích thuộc mục nguồn gốc tự nhiên, kinh tế - xã hội.","Dễ nhầm vì có chữ “không giải thích được”; phải đọc cả điều kiện lực lượng sản xuất và vị trí đề mục.","Đúng: là tên mục chứa đoạn trích ở trang 216.","Không phải nhóm nguồn gốc được giáo trình phân loại trong đoạn này."],"topic":"Tôn giáo","detail":"Đoạn này nằm trực tiếp dưới đề mục Nguồn gốc tự nhiên, kinh tế - xã hội ở trang 216: lực lượng sản xuất chưa phát triển, con người yếu đuối trước tự nhiên nên gán cho tự nhiên sức mạnh thần bí. C đúng theo vị trí và nội dung của đoạn. Cụm “không giải thích được” dễ gợi B, nhưng không được tách một cụm khỏi bối cảnh lực lượng sản xuất và sự lệ thuộc tự nhiên.","trick":"Lực lượng sản xuất thấp + bất lực trước tự nhiên → nguồn gốc tự nhiên, kinh tế - xã hội.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 216–217 (số in trên sách) · Bản trong Source · Nhóm ảnh 06 · Câu gốc 43","image":"assets/mln131/bo06/q43.png","sourceExam":"mln131_06","sourceId":43,"sourceKey":"mln131_unified_06_bank_v1","sourceLegacyKey":"mln131_unified_06_bank_v0","sourceLabel":"Nhóm ảnh 06 · Câu gốc 43","keywords":["lực lượng sản xuất chưa phát triển","yếu đuối, bất lực","nguồn gốc"]},{"id":38,"stem":"Để giải quyết tốt mối quan hệ dân tộc và tôn giáo, cần phải tuân thủ nguyên tắc nào?","options":["Giải quyết vấn đề tôn giáo trên cơ sở vấn đề dân tộc","Giải quyết vấn đề dân tộc trên cơ sở vấn đề tôn giáo","Luôn ưu tiên giải quyết vấn đề tôn giáo","Giải quyết vấn đề tôn giáo song song với vấn đề dân tộc"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: đúng chiều quan hệ của nguyên tắc ở trang 235.","Đảo chiều nguyên tắc mà sách nêu.","Sách không quy định luôn ưu tiên tôn giáo.","Diễn đạt chung, không nêu đúng nguyên tắc được hỏi."],"topic":"Dân tộc và tôn giáo","detail":"Trang 235 nêu trực tiếp nguyên tắc giải quyết vấn đề tôn giáo trên cơ sở vấn đề dân tộc, đặt trong cộng đồng quốc gia - dân tộc thống nhất, giữ vững độc lập, chủ quyền và thống nhất đất nước. A đúng. Không đảo chiều hai vế hoặc thay nguyên tắc cụ thể bằng cách nói chung là song song.","trick":"Tôn giáo trên cơ sở dân tộc; giữ vững cộng đồng quốc gia - dân tộc thống nhất.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 235 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 60","image":"assets/mln131/bo07/q60.png","keywords":["mối quan hệ dân tộc và tôn giáo","nguyên tắc"],"sourceExam":"mln131_07","sourceId":60,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 60"},{"id":39,"stem":"Đặc trưng bản chất nào của chủ nghĩa xã hội thể hiện đây là chế độ xã hội vì con người, do con người?","options":["Chủ nghĩa xã hội có nền kinh tế phát triển cao, dựa trên chế độ tư hữu về tư liệu sản xuất chủ yếu","Chủ nghĩa xã hội là chế độ xã hội do nhân dân lao động làm chủ","Chủ nghĩa xã hội giải phóng giai cấp công nhân, nhân dân lao động và đồng thời đàn áp giai cấp thống trị tàn bạo là giai cấp tư sản","Chủ nghĩa xã hội có nhà nước kiểu mới mang bản chất giai cấp công nhân, đại biểu cho lợi ích, quyền lực và ý chí của riêng giai cấp công nhân"],"correct":[1],"multiple":false,"gradable":true,"why":["Sai ở chữ tư hữu đối với tư liệu sản xuất chủ yếu; sách nêu công hữu.","Đúng: là đặc trưng chứa chính cụm mô tả trong câu hỏi.","Không phải đặc trưng được sách gắn trực tiếp với cụm vì con người, do con người.","Sai ở phạm vi riêng giai cấp công nhân; đoạn sách nói nhân dân lao động."],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Ngay dưới đặc trưng Chủ nghĩa xã hội là chế độ xã hội do nhân dân lao động làm chủ, trang 98 giải thích đây là xã hội vì con người và do con người. B khớp trực tiếp. A thay công hữu bằng tư hữu; D giới hạn lợi ích, quyền lực, ý chí vào riêng công nhân nên không khớp cách mô tả của sách.","trick":"Vì con người, do con người → nhân dân lao động làm chủ.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 98 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 4","image":"assets/mln131/bo07/q04.png","keywords":["vì con người, do con người","Đặc trưng bản chất"],"sourceExam":"mln131_07","sourceId":4,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 4"},{"id":40,"stem":"Một trong những hướng phát triển dân chủ mà Chủ tịch Hồ Chí Minh đã đề ra là gì?","options":["Dân chủ là một giá trị nhân loại chung","Dân chủ là người dân được tự do, hạnh phúc","Dân chủ là phát triển đất nước Xã hội chủ nghĩa ở Việt Nam","B và C đều đúng"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: là hướng thứ nhất được giáo trình nêu trực tiếp.","Không phải tên hướng phát triển được sách liệt kê ở đây.","Không phải tên hướng phát triển được sách liệt kê ở đây.","Không đúng vì B, C không khớp cách phân loại trong đoạn nguồn."],"topic":"Dân chủ và nhà nước","detail":"Cuối trang 127 và đầu trang 128, sách trình bày hai hướng Hồ Chí Minh phát triển dân chủ: dân chủ là một giá trị nhân loại chung; dân chủ là một thể chế chính trị, một chế độ xã hội. A đúng. Các phương án B, C không phải cách gọi hai hướng được liệt kê trong đoạn sách này; không chọn D chỉ vì B, C có sắc thái tích cực.","trick":"Hai hướng: giá trị nhân loại chung; thể chế chính trị, chế độ xã hội.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 127–128 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 16","image":"assets/mln131/bo07/q16.png","keywords":["hướng phát triển dân chủ","Chủ tịch Hồ Chí Minh"],"sourceExam":"mln131_07","sourceId":16,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 16"},{"id":41,"stem":"Trong cơ cấu xã hội - giai cấp ở Việt Nam hiện nay, giai cấp, tầng lớp nào có nhiệm vụ phát huy bản sắc văn hóa dân tộc và bảo vệ môi trường sinh thái?","options":["Giai cấp công nhân","Giai cấp nông dân","Tầng lớp trí thức","Đội ngũ doanh nhân"],"correct":[1],"multiple":false,"gradable":true,"why":["Không phải chủ thể của đoạn mô tả này.","Đúng: khớp phần về giai cấp nông dân ở trang 179–180.","Có vai trò về văn hóa, tri thức, nhưng không phải chủ thể trực tiếp trong đoạn đang hỏi.","Không phải chủ thể của đoạn mô tả này."],"topic":"Liên minh và cơ cấu xã hội","detail":"Phần về giai cấp nông dân nêu vai trò trong phát triển kinh tế - xã hội bền vững, giữ vững ổn định, an ninh, quốc phòng; giữ gìn, phát huy bản sắc văn hóa dân tộc và bảo vệ môi trường sinh thái. B là chủ thể được đoạn sách nhắc trực tiếp. Không suy ra các nhóm khác không có trách nhiệm văn hóa, môi trường.","trick":"Đoạn mô tả gắn bản sắc văn hóa và môi trường sinh thái với giai cấp nông dân.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 179–180 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 21","image":"assets/mln131/bo07/q21.png","keywords":["phát huy bản sắc văn hóa dân tộc","bảo vệ môi trường sinh thái"],"sourceExam":"mln131_07","sourceId":21,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 21"},{"id":42,"stem":"Hai yếu tố nào cấu thành cơ sở của lịch sử chính trị và lịch sử tư tưởng của thời đại?","options":["Chính trị xã hội và văn hóa","Cơ sở hạ tầng và kiến trúc thượng tầng","Sản xuất kinh tế và cơ cấu xã hội","Lực lượng sản xuất và quan hệ sản xuất"],"correct":[2],"multiple":false,"gradable":true,"why":["Không phải cặp yếu tố được câu dẫn nêu.","Là cặp khái niệm liên quan nhưng không điền đúng luận điểm đang hỏi.","Đúng: đúng cặp trong trích dẫn kéo dài qua trang 168–169.","Là cặp khái niệm liên quan đến phương thức sản xuất, không phải hai yếu tố được trích."],"topic":"Liên minh và cơ cấu xã hội","detail":"Sách dẫn Ph. Ăngghen: trong mọi thời đại lịch sử, sản xuất kinh tế và cơ cấu xã hội do sản xuất kinh tế tạo ra cùng cấu thành cơ sở của lịch sử chính trị và lịch sử tư tưởng. C đúng theo đúng cặp khái niệm được trích; không thay bằng các cặp lý luận có liên quan khác.","trick":"Cơ sở của lịch sử chính trị, tư tưởng → sản xuất kinh tế + cơ cấu xã hội.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 168–169 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 23","image":"assets/mln131/bo07/q23.png","keywords":["Hai yếu tố","lịch sử chính trị và lịch sử tư tưởng"],"sourceExam":"mln131_07","sourceId":23,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 23"},{"id":43,"stem":"Theo chủ nghĩa Mác - Lênin, tôn giáo là gì?","options":["Là một thiết chế xã hội phản ánh chân thật hiện thực khách quan","Là một hình thái ý thức xã hội, phản ánh hư ảo hiện thực khách quan","Là một cơ sở xã hội, phản ánh các ý chí, nguyện vọng của tín đồ theo một giáo lý nào đó","Là một thực thể xã hội, điều chỉnh tâm lý con người hiệu quả"],"correct":[1],"multiple":false,"gradable":true,"why":["Không khớp ở cả cách gọi và tính chất phản ánh trong định nghĩa.","Đúng: đúng định nghĩa mở đầu trang 214.","Không phải định nghĩa được sách nêu trong câu này.","Sách có cách tiếp cận thực thể xã hội, nhưng không định nghĩa như phương án D."],"topic":"Tôn giáo","detail":"Phần Bản chất của tôn giáo mở đầu bằng định nghĩa tôn giáo là một hình thái ý thức xã hội phản ánh hư ảo hiện thực khách quan. B khớp cách tiếp cận lý luận được câu hỏi sử dụng. Sách cũng xét tôn giáo như thực thể xã hội theo một cách tiếp cận khác, nhưng D không nêu định nghĩa được hỏi.","trick":"Theo định nghĩa trong mục bản chất: hình thái ý thức xã hội + phản ánh hư ảo.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 214 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 26","image":"assets/mln131/bo07/q26.png","keywords":["chủ nghĩa Mác - Lênin","tôn giáo là gì"],"sourceExam":"mln131_07","sourceId":26,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 26"},{"id":44,"stem":"Tôn trọng tự do tín ngưỡng cũng chính là tôn trọng vấn đề gì?","options":["Tôn trọng xã hội","Tôn trọng pháp luật","Tôn trọng quyền con người","Tôn trọng tôn giáo"],"correct":[2],"multiple":false,"gradable":true,"why":["Quá chung, không khớp kết luận trực tiếp của sách.","Có liên quan đến bảo đảm quyền nhưng không phải cụm sách dùng trong câu đang hỏi.","Đúng: khớp nhận định ở trang 220.","Không chỉ là tôn trọng tổ chức hay học thuyết tôn giáo; câu nhấn mạnh quyền của con người."],"topic":"Tôn giáo","detail":"Trang 220 nêu trực tiếp tôn trọng tự do tín ngưỡng cũng chính là tôn trọng quyền con người. Sách giải thích quyền theo, đổi hoặc không theo tôn giáo thuộc sự tự do lựa chọn của mỗi người, không được ép buộc hay cấm đoán.","trick":"Tự do tín ngưỡng, không tín ngưỡng → quyền con người.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 220 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 28","image":"assets/mln131/bo07/q28.png","keywords":["Tôn trọng tự do tín ngưỡng","tôn trọng vấn đề gì"],"sourceExam":"mln131_07","sourceId":28,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 28"},{"id":45,"stem":"Theo quan điểm của chủ nghĩa Mác - Lênin, nguyên nhân chính quyết định sự biến đổi của cộng đồng dân tộc là gì?","options":["Sự biến đổi của giai cấp thống trị","Sự biến đổi của kiến trúc thượng tầng xã hội","Sự biến đổi của cơ sở hạ tầng xã hội","Sự biến đổi của phương thức sản xuất"],"correct":[3],"multiple":false,"gradable":true,"why":["Không phải nguyên nhân được đoạn sách xác định trực tiếp.","Không phải cụm khái niệm được nguồn nêu.","Dễ nhầm với cơ sở kinh tế, nhưng không khớp cụm phương thức sản xuất trong luận điểm này.","Đúng: khớp câu mở đầu trang 196."],"topic":"Dân tộc","detail":"Mở đầu khái niệm dân tộc, trang 196 xác định chính sự biến đổi của phương thức sản xuất là nguyên nhân quyết định sự biến đổi của cộng đồng dân tộc. D khớp trực tiếp; không thay cụm này bằng giai cấp thống trị, kiến trúc thượng tầng hoặc cơ sở hạ tầng.","trick":"Nguyên nhân quyết định biến đổi cộng đồng dân tộc → phương thức sản xuất.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 196 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 29","image":"assets/mln131/bo07/q29.png","keywords":["nguyên nhân chính quyết định","biến đổi của cộng đồng dân tộc"],"sourceExam":"mln131_07","sourceId":29,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 29"},{"id":46,"stem":"Theo quan điểm của Đảng ta về vấn đề dân tộc, ưu tiên phát triển kinh tế xã hội các vùng dân tộc và miền núi trước hết cần tập trung phát triển các yếu tố nào?","options":["Giao thông và cơ sở hạ tầng, xóa đói, giảm nghèo","Kết cấu hạ tầng kỹ thuật, xóa đói giảm nghèo, y tế, giáo dục","Giao thông và kiến trúc thượng tầng, xóa đói giảm nghèo","Giao thông và kết cấu hạ tầng, y tế, giáo dục"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: khớp đầy đủ cụm sau trước hết ở trang 211.","Liệt kê các nội dung cần thiết nhưng không khớp cụm được hỏi.","Sai ở kiến trúc thượng tầng; sách nói cơ sở hạ tầng.","Thay xóa đói, giảm nghèo bằng y tế, giáo dục nên không đúng luận điểm được trích."],"topic":"Dân tộc","detail":"Trong quan điểm cơ bản của Đảng về vấn đề dân tộc, trang 211 dùng đúng cụm “trước hết” cho việc tập trung phát triển giao thông và cơ sở hạ tầng, xóa đói, giảm nghèo. A khớp. Y tế, giáo dục đều quan trọng, nhưng không được tự thêm hoặc thay thành phần khi đề đang hỏi đúng luận điểm ưu tiên này.","trick":"Thấy “trước hết” → giao thông, cơ sở hạ tầng, xóa đói, giảm nghèo.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 211 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 30","image":"assets/mln131/bo07/q30.png","keywords":["ưu tiên","trước hết","vùng dân tộc và miền núi"],"sourceExam":"mln131_07","sourceId":30,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 30"},{"id":47,"stem":"Trong hai mặt của vấn đề tôn giáo, mặt nào phản ánh mâu thuẫn mang tính chất đối kháng giữa các giai cấp và các thế lực lợi dụng tôn giáo chống lại sự nghiệp cách mạng của nhân dân lao động?","options":["Mặt chính trị","Mặt tư tưởng","Không có mặt nào có tính chất mâu thuẫn đối kháng","Cả hai mặt đều có tính chất mâu thuẫn đối kháng"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: khớp cách phân biệt ở trang 221.","Mặt tư tưởng được sách xác định không mang tính đối kháng.","Không đúng vì sách nêu mặt chính trị có mâu thuẫn đối kháng.","Không đúng vì đánh đồng hai mặt."],"topic":"Tôn giáo","detail":"Trang 221 phân biệt mặt chính trị phản ánh mâu thuẫn đối kháng về lợi ích giữa các giai cấp, giữa thế lực lợi dụng tôn giáo và nhân dân lao động. Mặt tư tưởng biểu hiện khác biệt niềm tin và phản ánh mâu thuẫn không đối kháng. A đúng. Không đồng nhất khác biệt niềm tin với chống đối chính trị.","trick":"Chính trị → đối kháng về lợi ích; tư tưởng → khác biệt niềm tin, không đối kháng.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 221 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 31","image":"assets/mln131/bo07/q31.png","keywords":["mâu thuẫn mang tính chất đối kháng","lợi dụng tôn giáo"],"sourceExam":"mln131_07","sourceId":31,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 31"},{"id":48,"stem":"Tại sao nói gia đình là tế bào của xã hội?","options":["Vì bất kì ai cũng có gia đình riêng, có con cái và cha mẹ","Vì gia đình sản xuất ra tư liệu tiêu dùng, tư liệu sản xuất và tái sản xuất ra con người","Vì gia đình là cơ chế quản lý xã hội ở cấp độ nhỏ nhất, không thể phân chia được nữa","Vì gia đình là nền tảng tinh thần của xã hội"],"correct":[1],"multiple":false,"gradable":true,"why":["Khái quát tuyệt đối về hoàn cảnh mọi cá nhân, không phải căn cứ lý luận được sách nêu.","Đúng: khớp đoạn giải thích tại trang 242.","Không phải nghĩa của ẩn dụ tế bào xã hội trong sách.","Không khớp nội dung giải thích được hỏi."],"topic":"Gia đình","detail":"Sách giải thích gia đình là tế bào tự nhiên, đơn vị cơ sở tạo nên cơ thể xã hội thông qua việc sản xuất tư liệu tiêu dùng, tư liệu sản xuất và tái sản xuất ra con người. B phù hợp. Không hiểu tế bào xã hội theo nghĩa một đơn vị quản lý không thể chia nhỏ.","trick":"Gia đình là tế bào → sản xuất đời sống vật chất và tái sản xuất con người.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 241–242 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 32","image":"assets/mln131/bo07/q32.png","keywords":["gia đình","tế bào của xã hội"],"sourceExam":"mln131_07","sourceId":32,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 32"},{"id":49,"stem":"Quy mô gia đình ở Việt Nam hiện nay tồn tại theo xu hướng nào?","options":["Thu nhỏ số lượng thành viên trong gia đình","Mở rộng số lượng thành viên trong gia đình","Liên kết các gia đình đơn","Quy mô nhỏ ở nông thôn và quy mô lớn ở thành thị"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: khớp xu hướng được sách nêu trực tiếp.","Đảo ngược xu hướng của nguồn.","Không phải xu hướng quy mô được mô tả.","Không khớp mô tả gia đình hạt nhân phổ biến ở cả đô thị và nông thôn."],"topic":"Gia đình","detail":"Trang 258 mô tả quy mô gia đình Việt Nam theo xu hướng thu nhỏ, ít thành viên hơn; gia đình hạt nhân trở nên phổ biến cả ở đô thị và nông thôn. A đúng. Đây là xu hướng khái quát trong giáo trình, không khẳng định mọi gia đình đều có cùng quy mô.","trick":"Xu hướng quy mô → thu nhỏ; gia đình hạt nhân phổ biến.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 258 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 35","image":"assets/mln131/bo07/q35.png","keywords":["Quy mô gia đình","xu hướng"],"sourceExam":"mln131_07","sourceId":35,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 35"},{"id":50,"stem":"Trong các chế độ xã hội trước, sự thống trị của người đàn ông trong gia đình là kết quả của việc gì?","options":["Của sự thống trị về kinh tế","Của sự phát triển chế độ quân chủ","Của sự thống trị về văn hóa","Của sự thống trị về chính trị"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: đúng luận điểm tại trang 251.","Không phải nguyên nhân được đoạn sách xác định.","Không phải căn cứ trực tiếp được câu trích nêu.","Không phải căn cứ trực tiếp được câu trích nêu."],"topic":"Gia đình","detail":"Trong phần cơ sở kinh tế - xã hội xây dựng gia đình, sách nêu trực tiếp sự thống trị của người đàn ông trong gia đình là kết quả sự thống trị của họ về kinh tế. A khớp luận điểm được hỏi trong phân tích lịch sử này.","trick":"Thống trị trong gia đình ở các chế độ trước → cơ sở thống trị về kinh tế.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 251 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 37","image":"assets/mln131/bo07/q37.png","keywords":["các chế độ xã hội trước","sự thống trị","trong gia đình"],"sourceExam":"mln131_07","sourceId":37,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 37"},{"id":51,"stem":"Vấn đề: ... phải “bắc những nhịp cầu nhỏ” đi xuyên qua kinh tế tư bản để từng bước xây dựng Chủ nghĩa xã hội. Đồng thời, lưu ý “chúng ta phải hiểu những đường lối, thể thức, thủ đoạn và phương sách trung gian cần thiết để chuyển từ những quan hệ tiền tư bản chủ nghĩa lên chủ nghĩa xã hội. Đó là mấu chốt của vấn đề”. Thông qua vấn đề trên hãy cho biết V.I. Lênin muốn đề cập đến đó là hình thức cơ bản nào của thời kỳ quá độ lên chủ nghĩa xã hội?","options":["Không trải qua","Trực tiếp","Vừa trực tiếp vừa gián tiếp","Gián tiếp"],"correct":[3],"multiple":false,"gradable":true,"why":["Đề vẫn nói đến quá trình quá độ và các bước trung gian.","Trực tiếp là loại được sách gắn với nước đã qua tư bản phát triển.","Không phải tên một loại trong cặp phân loại của đoạn sách.","Đúng: suy ra từ điều kiện xuất phát và cách phân loại ở trang 105."],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Trang 97 bàn về những nước chưa trải qua chủ nghĩa tư bản đi lên chủ nghĩa xã hội, phải bắc những chiếc cầu nhỏ qua chủ nghĩa tư bản nhà nước và học hỏi kinh nghiệm các nước phát triển. Trang 105 phân biệt quá độ trực tiếp ở nước đã trải qua tư bản phát triển với quá độ gián tiếp ở nước chưa trải qua tư bản phát triển. Từ bối cảnh tiền tư bản và các phương sách trung gian trong đề, suy ra D - gián tiếp. Không nhầm từ từng bước với một đáp án phân loại riêng.","trick":"Tiền tư bản + những cầu nối, bước trung gian → quá độ gián tiếp.","caution":"Chốt D bằng bối cảnh và cách phân loại trong giáo trình. Trang 97 dùng cụm những chiếc cầu nhỏ vững chắc qua chủ nghĩa tư bản nhà nước; ảnh diễn đạt khác. Không coi toàn bộ đoạn trên ảnh là trích nguyên văn đã được kiểm chứng.","reference":"Giáo trình CNXH khoa học (2021), trang 97, 105–106 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 40","image":"assets/mln131/bo07/q40.png","keywords":["bắc những nhịp cầu nhỏ","phương sách trung gian","tiền tư bản chủ nghĩa"],"sourceExam":"mln131_07","sourceId":40,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 40"},{"id":52,"stem":"Điều kiện khách quan quy định sứ mệnh lịch sử của giai cấp công nhân là gì? (Chọn 2 đáp án đúng)","options":["Địa vị kinh tế của giai cấp công nhân","Địa vị chính trị - xã hội của giai cấp công nhân","Xuất thân từ giai cấp nông dân trong xã hội phong kiến cũ","Là giai cấp có khả năng thống trị được toàn thể xã hội xây dựng xã hội mới"],"correct":[0,1],"multiple":true,"gradable":true,"why":["Đúng: điều kiện khách quan thứ nhất ở trang 60.","Đúng: điều kiện khách quan thứ hai ở trang 61.","Không phải điều kiện khách quan được sách xác định.","Không thuộc cặp điều kiện được liệt kê; không thay thế được việc chỉ rõ hai địa vị."],"topic":"Giai cấp công nhân","detail":"Mục Điều kiện khách quan liệt kê hai căn cứ: địa vị kinh tế và địa vị chính trị - xã hội của giai cấp công nhân. Chọn A và B. C không phải căn cứ phổ quát của sứ mệnh lịch sử; D không phải điều kiện thứ ba được sách liệt kê.","trick":"Hai điều kiện khách quan → địa vị kinh tế + địa vị chính trị - xã hội.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 60–62 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 41","image":"assets/mln131/bo07/q41.png","keywords":["Điều kiện khách quan","sứ mệnh lịch sử","Chọn 2 đáp án đúng"],"sourceExam":"mln131_07","sourceId":41,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 41"},{"id":53,"stem":"Theo V.I. Lênin, các xu hướng khách quan của sự phát triển quan hệ dân tộc là gì?","options":["Cộng đồng dân cư muốn tách ra để hình thành cộng đồng dân tộc độc lập","Các dân tộc trong từng quốc gia, thậm chí các dân tộc ở nhiều quốc gia muốn liên hiệp lại với nhau","Cộng đồng dân tộc yếu thế có xu hướng sáp nhập với các dân tộc có trình độ phát triển cao hơn","Cộng đồng dân tộc phát triển hưng thịnh sẽ có ý định tách ra hình thành quốc gia - dân tộc độc lập"],"correct":[0,1],"multiple":true,"gradable":true,"why":["Đúng: khớp xu hướng thứ nhất ở trang 201.","Đúng: khớp xu hướng thứ hai ở trang 202.","Không đồng nhất liên hiệp tự nguyện với việc dân tộc yếu thế sáp nhập vào dân tộc mạnh hơn.","Không khớp nguyên nhân và cách mô tả xu hướng thứ nhất; hưng thịnh không tự suy ra ly khai."],"topic":"Dân tộc","detail":"Sách nêu hai xu hướng: cộng đồng dân cư muốn tách ra hình thành dân tộc độc lập; các dân tộc trong một hoặc nhiều quốc gia muốn liên hiệp lại. A và B đúng. C biến liên hiệp thành sự sáp nhập do yếu thế; D tự thêm điều kiện hưng thịnh và kết luận tất yếu tách ra, không phải cách diễn đạt của sách.","trick":"Hai xu hướng cùng tồn tại → tách ra để độc lập và liên hiệp lại.","caution":"Có hai đáp án đúng theo giáo trình. Bản ôn ghi Chọn nhiều đáp án và chấm A, B; không ép chọn một phương án dù ảnh không ghi rõ số lượng.","reference":"Giáo trình CNXH khoa học (2021), trang 201–202 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 42","image":"assets/mln131/bo07/q42.png","keywords":["các xu hướng khách quan","phát triển quan hệ dân tộc"],"sourceExam":"mln131_07","sourceId":42,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 42"},{"id":54,"stem":"Bản chất dân chủ xã hội chủ nghĩa ở Việt Nam được thực hiện thông qua những hình thức nào?","options":["Dân chủ đại diện và dân chủ cơ sở","Dân chủ trực tiếp và dân chủ tập trung","Dân chủ gián tiếp và dân chủ vô sản","Dân chủ trực tiếp và dân chủ gián tiếp"],"correct":[3],"multiple":false,"gradable":true,"why":["Đại diện tương ứng gián tiếp, nhưng ghép với cơ sở không thành cặp phân loại trong đoạn này.","Trộn hình thức trực tiếp với nguyên tắc tập trung.","Trộn hình thức thực hiện với loại hình dân chủ vô sản.","Đúng: đủ hai hình thức được sách xác định."],"topic":"Dân chủ và nhà nước","detail":"Trang 153 nêu trực tiếp hai hình thức thực hiện là dân chủ gián tiếp và dân chủ trực tiếp; gián tiếp còn gọi là đại diện. D khớp đầy đủ cặp hình thức. Không trộn hình thức thực hiện với nguyên tắc tập trung hoặc với loại hình dân chủ vô sản.","trick":"Hai hình thức thực hiện → trực tiếp và gián tiếp (đại diện).","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 153 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 46","image":"assets/mln131/bo07/q46.png","keywords":["Bản chất dân chủ","hình thức nào"],"sourceExam":"mln131_07","sourceId":46,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 46"},{"id":55,"stem":"Trong thời kỳ quá độ lên chủ nghĩa xã hội, cơ cấu xã hội - giai cấp được xác định là gì?","options":["Tổng thể các giai cấp cơ bản và các tầng lớp, nhóm xã hội không có mâu thuẫn đối kháng về mặt lợi ích.","Tổng thể các giai cấp, tầng lớp, các nhóm xã hội có mối quan hệ hợp tác và gắn bó chặt chẽ với nhau.","Tổng thể các giai cấp không cơ bản và các tầng lớp trong xã hội, bao gồm cả các giai cấp có mâu thuẫn đối kháng về lợi ích.","Tổng thể các giai cấp, tầng lớp trong liên minh công - nông - trí, có mối quan hệ hợp tác, gắn bó chặt chẽ với nhau."],"correct":[1],"multiple":false,"gradable":true,"why":["Thêm điều kiện không có mâu thuẫn đối kháng và giới hạn giai cấp cơ bản, không khớp định nghĩa.","Đúng: khớp định nghĩa ở trang 166.","Giới hạn vào giai cấp không cơ bản nên không bao quát định nghĩa.","Thu hẹp toàn bộ cơ cấu vào khối liên minh công - nông - trí."],"topic":"Liên minh và cơ cấu xã hội","detail":"Trang 166 định nghĩa cơ cấu xã hội - giai cấp thời kỳ quá độ là tổng thể các giai cấp, tầng lớp, các nhóm xã hội có mối quan hệ hợp tác và gắn bó chặt chẽ với nhau. B đúng. D thu hẹp toàn bộ cơ cấu vào liên minh công - nông - trí; A, C đều thêm hoặc giới hạn phạm vi không khớp định nghĩa.","trick":"Cơ cấu xã hội - giai cấp → tổng thể các giai cấp, tầng lớp, nhóm xã hội; không chỉ khối liên minh.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 166 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 47","image":"assets/mln131/bo07/q47.png","keywords":["thời kỳ quá độ","cơ cấu xã hội - giai cấp","xác định"],"sourceExam":"mln131_07","sourceId":47,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 47"},{"id":56,"stem":"Câu nói sau đây là của ai khi nói về gia đình: “... nhiều gia đình cộng lại mới thành xã hội, xã hội tốt thì gia đình càng tốt, gia đình tốt thì xã hội mới tốt. Hạt nhân của xã hội là gia đình”?","options":["Chủ tịch Hồ Chí Minh","C. Mác","Ph. Ăngghen","V.I. Lênin"],"correct":[0],"multiple":false,"gradable":true,"why":["Đúng: được sách ghi rõ tác giả và chú thích ở trang 242.","Không phải tác giả câu này theo giáo trình.","Đoạn trước dẫn Ăngghen về sản xuất và tái sản xuất đời sống, không phải câu đang hỏi.","Không phải tác giả câu này theo giáo trình."],"topic":"Gia đình","detail":"Trong mục Gia đình là tế bào của xã hội, trang 242 dẫn nguyên câu này và xác định là lời Chủ tịch Hồ Chí Minh; chú thích dẫn Hồ Chí Minh: Toàn tập, tập 12, trang 300. A đúng. Không nhầm với câu của Ph. Ăngghen về hai loại sản xuất ở đoạn trước.","trick":"Nhiều gia đình cộng lại; hạt nhân xã hội là gia đình → Hồ Chí Minh.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 242 (số in trên sách) · Bản trong Source · Nhóm ảnh 07 · Câu gốc 50","image":"assets/mln131/bo07/q50.png","keywords":["nhiều gia đình cộng lại","Hạt nhân của xã hội là gia đình","của ai"],"sourceExam":"mln131_07","sourceId":50,"sourceKey":"mln131_unified_07_bank_v1","sourceLegacyKey":"mln131_unified_07_bank_v0","sourceLabel":"Nhóm ảnh 07 · Câu gốc 50"},{"id":57,"stem":"Ba phát kiến vĩ đại của C. Mác và Ph. Ăngghen là gì?","options":["Chủ nghĩa duy vật, Chủ nghĩa duy vật lịch sử, Học thuyết về giá trị thặng dư","Chủ nghĩa duy vật lịch sử, Chủ nghĩa duy tâm biện chứng, Học thuyết về giá trị thặng dư","Học thuyết giá trị thặng dư, Chủ nghĩa duy vật lịch sử, Phép biện chứng duy tâm","Chủ nghĩa duy vật lịch sử, Học thuyết về giá trị thặng dư, Học thuyết về sứ mệnh lịch sử toàn thế giới của giai cấp công nhân"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Nhập môn CNXH khoa học","detail":"Mục Ba phát kiến vĩ đại lần lượt liệt kê chủ nghĩa duy vật lịch sử, học thuyết về giá trị thặng dư và học thuyết về sứ mệnh lịch sử toàn thế giới của giai cấp công nhân. D chứa đủ ba nội dung. A thiếu phát kiến thứ ba; B và C đưa duy tâm vào danh sách nên không khớp.","trick":"Ba phát kiến: duy vật lịch sử → giá trị thặng dư → sứ mệnh lịch sử giai cấp công nhân.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 19–20 (số in trên sách) · Bản trong Source · Nhóm ảnh 08 · Câu gốc 6","image":"assets/mln131/bo08/q06.png","keywords":["Ba phát kiến vĩ đại","C. Mác và Ph. Ăngghen"],"sourceExam":"mln131_08","sourceId":6,"sourceKey":"mln131_unified_08_bank_v1","sourceLegacyKey":"mln131_unified_08_bank_v0","sourceLabel":"Nhóm ảnh 08 · Câu gốc 6"},{"id":59,"stem":"Về nội dung chính trị - xã hội, sứ mệnh lịch sử của giai cấp công nhân được thể hiện như thế nào?","options":["Giai cấp công nhân cùng với nhân dân lao động dưới sự lãnh đạo của Đảng Cộng sản phải tiến hành cách mạng chính trị lật đổ quyền thống trị của giai cấp tư sản","Giai cấp công nhân phải lãnh đạo được các giai cấp khác và lãnh đạo được Đảng Cộng sản để tiến hành cách mạng tư sản xóa bỏ chế độ thống trị của giai cấp tư sản","Giai cấp công nhân phải cùng với nhân dân lao động lãnh đạo Đảng Cộng sản tiến hành cách mạng chính trị lật đổ chính quyền của giai cấp phong kiến","Giai cấp công nhân phải xác lập được quyền thống trị nhân dân lao động và các giai cấp khác bằng cách thực hiện cách mạng lật đổ chính quyền của giai cấp tư sản"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Giai cấp công nhân","detail":"Trang 58 xác định giai cấp công nhân cùng nhân dân lao động, dưới sự lãnh đạo của Đảng Cộng sản, tiến hành cách mạng chính trị để lật đổ quyền thống trị, xóa bỏ bóc lột, áp bức, giành quyền lực về tay công nhân và nhân dân lao động. A khớp. B và C đảo quan hệ lãnh đạo với Đảng; B còn gọi sai là cách mạng tư sản. D biến quyền làm chủ của nhân dân thành thống trị nhân dân.","trick":"Công nhân + nhân dân lao động; dưới sự lãnh đạo của Đảng; cách mạng chính trị.","caution":"Ảnh gốc thiếu chữ trị sau cách mạng chính ở A; bản chữ bổ sung lỗi đánh máy theo thuật ngữ tại trang 58, giữ ảnh để đối chiếu.","reference":"Giáo trình CNXH khoa học (2021), trang 58 (số in trên sách) · Bản trong Source · Nhóm ảnh 08 · Câu gốc 14","image":"assets/mln131/bo08/q14.png","keywords":["nội dung chính trị - xã hội","sứ mệnh lịch sử"],"sourceExam":"mln131_08","sourceId":14,"sourceKey":"mln131_unified_08_bank_v1","sourceLegacyKey":"mln131_unified_08_bank_v0","sourceLabel":"Nhóm ảnh 08 · Câu gốc 14"},{"id":60,"stem":"Nội dung sứ mệnh lịch sử của giai cấp công nhân Việt Nam hiện nay thực hiện trên những phương diện nào?","options":["Giai cấp công nhân thực hiện xây dựng con người mới xã hội chủ nghĩa","Giai cấp công nhân thực hiện xây dựng đạo đức và lối sống mới xã hội chủ nghĩa","Giai cấp công nhân thực hiện xây dựng và củng cố ý thức hệ tiên tiến của mình","Kinh tế; Chính trị - xã hội; Văn hóa, tư tưởng"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Giai cấp công nhân","detail":"Mục về sứ mệnh lịch sử của giai cấp công nhân Việt Nam hiện nay chia thành ba tiểu mục: kinh tế; chính trị - xã hội; văn hóa, tư tưởng. D bao quát đủ ba phương diện. A, B, C chỉ nêu những nội dung thuộc một phương diện nên không trả lời đủ câu hỏi.","trick":"Hỏi những phương diện → chọn đủ kinh tế; chính trị - xã hội; văn hóa, tư tưởng.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 76–79 (số in trên sách) · Bản trong Source · Nhóm ảnh 08 · Câu gốc 15","image":"assets/mln131/bo08/q15.png","keywords":["giai cấp công nhân Việt Nam hiện nay","những phương diện"],"sourceExam":"mln131_08","sourceId":15,"sourceKey":"mln131_unified_08_bank_v1","sourceLegacyKey":"mln131_unified_08_bank_v0","sourceLabel":"Nhóm ảnh 08 · Câu gốc 15"},{"id":61,"stem":"Điền vào chỗ trống: C. Mác và Ph. Ăngghen chỉ rõ: “Từ chỗ là những hình thức phát triển của các lực lượng sản xuất, những quan hệ sản xuất ấy trở thành những xiềng xích của các lực lượng sản xuất. Khi đó bắt đầu thời đại...”","options":["Một cuộc tổng tiến công","Một cuộc cải cách","Tất cả đều đúng","Một cuộc cách mạng"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Trang 91 dẫn câu kết là thời đại một cuộc cách mạng xã hội. D là phương án điền khớp. Các quan hệ sản xuất từ hình thức phát triển chuyển thành xiềng xích của lực lượng sản xuất là bối cảnh của cách mạng xã hội trong đoạn này.","trick":"Quan hệ sản xuất thành xiềng xích lực lượng sản xuất → cách mạng xã hội.","caution":"Ảnh diễn đạt những quan hệ sản xuất ấy, còn câu dẫn trong sách viết những quan hệ ấy; đáp án không thay đổi.","reference":"Giáo trình CNXH khoa học (2021), trang 91 (số in trên sách) · Bản trong Source · Nhóm ảnh 08 · Câu gốc 26","image":"assets/mln131/bo08/q26.png","keywords":["xiềng xích","Khi đó bắt đầu thời đại"],"sourceExam":"mln131_08","sourceId":26,"sourceKey":"mln131_unified_08_bank_v1","sourceLegacyKey":"mln131_unified_08_bank_v0","sourceLabel":"Nhóm ảnh 08 · Câu gốc 26"},{"id":62,"stem":"Đâu là một phương hướng trong việc phát huy vai trò của phụ nữ trong cơ cấu xã hội Việt Nam hiện nay?","options":["Có kế hoạch chăm sóc sức khỏe sinh sản, đảm bảo quyền tự do kế hoạch hóa gia đình của phụ nữ","Tăng tỷ lệ phụ nữ tham gia vào các cấp ủy và bộ máy quản lý các cấp","Có chính sách ưu đãi xã hội đối với nữ giới để đảm bảo quyền bình đẳng","Tăng cường đội ngũ doanh nhân nữ giới"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Liên minh và cơ cấu xã hội","detail":"Đoạn Đối với phụ nữ ở trang 190 nêu trực tiếp việc tăng tỷ lệ phụ nữ tham gia vào cấp ủy và bộ máy quản lý các cấp, cùng các hướng nâng cao trình độ, đời sống, bình đẳng giới và hoàn thiện chính sách lao động nữ. B khớp trực tiếp phương hướng được giáo trình liệt kê. Không suy ra các biện pháp khác hoàn toàn vô ích chỉ vì không phải đáp án của đoạn này.","trick":"Phát huy vai trò phụ nữ trong cơ cấu xã hội → tăng tham gia cấp ủy, bộ máy quản lý.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 190–191 (số in trên sách) · Bản trong Source · Nhóm ảnh 08 · Câu gốc 35","image":"assets/mln131/bo08/q35.png","keywords":["phát huy vai trò của phụ nữ","cơ cấu xã hội Việt Nam hiện nay"],"sourceExam":"mln131_08","sourceId":35,"sourceKey":"mln131_unified_08_bank_v1","sourceLegacyKey":"mln131_unified_08_bank_v0","sourceLabel":"Nhóm ảnh 08 · Câu gốc 35"},{"id":63,"stem":"Theo cấp độ quốc gia, đâu là tín ngưỡng truyền thống quan trọng của dân tộc Việt Nam?","options":["Tín ngưỡng thờ cúng tổ tiên","Tín ngưỡng thành hoàng","Tín ngưỡng thờ cúng vua Hùng","Tín ngưỡng thờ mẫu"],"correct":[2],"multiple":false,"gradable":true,"why":[],"topic":"Dân tộc và tôn giáo","detail":"Trang 230 phân biệt tín ngưỡng ở gia đình, dòng họ và làng xã; trang 231 chuyển sang cấp độ quốc gia và việc hướng về cội nguồn chung nơi các Vua Hùng có công dựng nước. C khớp cấp độ được hỏi. Không chọn A chỉ vì thờ cúng tổ tiên là tín ngưỡng truyền thống quan trọng ở phạm vi gia đình.","trick":"Cấp độ quốc gia, cội nguồn dân tộc → thờ cúng Vua Hùng.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 230–231 (số in trên sách) · Bản trong Source · Nhóm ảnh 08 · Câu gốc 41","image":"assets/mln131/bo08/q41.png","keywords":["cấp độ quốc gia","tín ngưỡng truyền thống"],"sourceExam":"mln131_08","sourceId":41,"sourceKey":"mln131_unified_08_bank_v1","sourceLegacyKey":"mln131_unified_08_bank_v0","sourceLabel":"Nhóm ảnh 08 · Câu gốc 41"},{"id":64,"stem":"Trong quá trình giải quyết vấn đề tôn giáo, chúng ta cần phân biệt hai mặt nào của tôn giáo?","options":["Chính trị và pháp quyền","Chính trị và tư tưởng","Tư tưởng và văn hóa","Giáo dục và tư tưởng"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Tôn giáo","detail":"Một nguyên tắc được giáo trình nêu là phân biệt hai mặt chính trị và tư tưởng trong giải quyết vấn đề tôn giáo. B đúng. Mặt chính trị gắn với quan hệ lợi ích và việc lợi dụng tôn giáo; mặt tư tưởng liên quan đến khác biệt nhận thức, niềm tin. Không đồng nhất tín ngưỡng với hành vi chống đối chính trị.","trick":"Hai mặt cần phân biệt → chính trị và tư tưởng.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 221–222 (số in trên sách) · Bản trong Source · Nhóm ảnh 08 · Câu gốc 45","image":"assets/mln131/bo08/q45.png","keywords":["giải quyết vấn đề tôn giáo","phân biệt hai mặt"],"sourceExam":"mln131_08","sourceId":45,"sourceKey":"mln131_unified_08_bank_v1","sourceLegacyKey":"mln131_unified_08_bank_v0","sourceLabel":"Nhóm ảnh 08 · Câu gốc 45"}]}});